<script setup lang="ts">
import { computed } from 'vue';
import { state as stateSource, mode } from '../workbench/store';
const state=stateSource;
import { objectKey, aspectNames as aspectNamesSource } from '../workbench/model';
const aspectNames=aspectNamesSource;
import { route as routeSource, go, setQuery, back } from '../workbench/navigation';
const route=routeSource;
import ModelLink from './ModelLink.vue';
import AccessGate from './AccessGate.vue';
import PagingBar from './PagingBar.vue';
const studentSpaces=computed(()=>route.scope?state.spaces.filter(s=>s.studentId===route.id&&s.id===route.scope):[]);
const students=computed(()=>[...new Map(state.spaces.map(s=>[s.studentId,{id:s.studentId,name:s.studentName}])).values()].filter(s=>!route.q||`${s.id} ${s.name}`.includes(route.q)));
function openActivity(id:string){go('activity',{id,scope:mode.value==='demo'?id:'',returnTo:location.hash});}
</script>
<template><div class="wb-page"><header class="page-header"><div><button v-if="route.id" class="text-link" @click="back('students')">← 返回来源</button><h2>学生状态</h2><p class="page-desc">{{mode==='demo'?'按学生和空间查阅分方面判断，沿真实含义的示例记录核对依据。':'真实会话只显示已记录输入、模型输出和运行信息；不混入示例评价。'}}</p></div></header>
  <template v-if="route.page==='students'"><p v-if="mode==='real'" class="callout">当前真实对话没有正式学生身份与 Learner State，不能将本地会话冒充某位示例学生的能力。请到“交互审查”查看真实记录。</p><template v-else-if="!route.id"><div class="toolbar"><label>查找学生<input :value="route.q" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})" placeholder="姓名或编号"/></label></div><section class="table-card"><table class="data-table"><thead><tr><th>学生</th><th>学习空间</th><th>近期活动</th><th>操作</th></tr></thead><tbody><tr v-for="s in students.slice((route.p-1)*10,route.p*10)" :key="s.id"><td>{{s.name}}<small>{{s.id}}</small></td><td>{{state.spaces.filter(x=>x.studentId===s.id).length}}</td><td>{{state.activities.filter(a=>state.spaces.some(x=>x.id===a.ls&&x.studentId===s.id)).length}} 条示例记录</td><td><button class="btn" @click="go('students',{id:s.id})">查看状态</button></td></tr></tbody></table></section><PagingBar :total="students.length"/></template><AccessGate v-else :subject="route.id"><div class="toolbar"><label>学习空间<select aria-label="学习空间" :value="route.scope" @change="setQuery({scope:($event.target as HTMLSelectElement).value})"><option value="">选择空间查看，不合并能力</option><option v-for="s in state.spaces.filter(s=>s.studentId===route.id)" :key="s.id" :value="s.id">{{s.name}} · {{s.id}}</option></select></label></div><p v-if="!route.scope" class="callout">请选择一个学习空间查看具体判断；课程之间不合并能力状态。</p><section v-for="s in studentSpaces" :key="s.id" class="panel"><div class="row-between"><h3>{{s.name}}</h3><button class="text-link" @click="go('learning-spaces',{id:s.id})">采用版本与目标</button></div><p class="muted">{{s.studentName}} · {{s.id}} · 不借用其他空间的个人判断</p><template v-if="state.objects.some(o=>o.kind==='belief'&&o.fields.学习空间===s.id)"><section v-for="b in state.objects.filter(o=>o.kind==='belief'&&o.fields.学习空间===s.id)" :key="objectKey(b)" class="belief-card"><ModelLink :to="objectKey(b)" :scope="state.activities.find(a=>a.objects.includes(objectKey(b)))?.id"/><p v-if="state.invalidated[objectKey(b)]" class="callout danger">已退出当前使用，待重新推断。原判断仅作历史查看。</p><div class="aspect-grid"><div v-for="a in b.states" :key="a.key"><span>{{aspectNames[a.key]}}</span><strong>{{state.invalidated[objectKey(b)]?'待重处理':a.judgment}}</strong><small>{{a.uncertainty}}</small><ModelLink v-for="e in a.evidence" :key="e" :to="e" :scope="state.activities.find(x=>x.objects.includes(e))?.id" label="查看依据"/></div></div></section></template><p v-else class="empty">尚未形成此空间的能力判断。不是未掌握，也不从其他空间复制。</p><h4>相关活动</h4><div class="list-row" v-for="a in state.activities.filter(a=>a.ls===s.id)" :key="a.id"><button class="text-link" @click="openActivity(a.id)">{{a.name}}</button><span>{{a.at}}</span></div></section></AccessGate></template>
</div></template>
